mapper.select:
SELECT MIN(stat_date) AS dateFrom, MAX(stat_date) AS dateTo, COUNT(DISTINCT stat_date) AS days, COUNT(DISTINCT CASE WHEN charge > 0 THEN campaign_id END) AS planCount, ROUND(SUM(charge), 2) AS charge, SUM(ad_pv) AS adPv, SUM(click) AS click, ROUND(SUM(click) / NULLIF(SUM(ad_pv), 0) * 100, 4) AS ctrPercent, ROUND(SUM(charge) / NULLIF(SUM(click), 0), 4) AS cpc, ROUND(SUM(charge) / NULLIF(SUM(ad_pv), 0) * 1000, 4) AS cpm, ROUND(SUM(gmv_total), 2) AS gmvTotal, ROUND(SUM(gmv_direct), 2) AS gmvDirect, SUM(order_total) AS orderTotal, ROUND(SUM(gmv_total) / NULLIF(SUM(charge), 0), 2) AS roi, SUM(cart_count) AS cartCount, SUM(collect_total) AS collectTotal, DATE_FORMAT(MAX(update_time), '%Y-%m-%d %H:%i') AS lastCollectedAt FROM promo_cost_daily
stat_date BETWEEN #{dateFrom} AND #{dateTo}
AND plan_type = #{planType}

SELECT stat_date AS statDate, ROUND(SUM(charge), 2) AS charge, SUM(ad_pv) AS adPv, SUM(click) AS click, ROUND(SUM(click) / NULLIF(SUM(ad_pv), 0) * 100, 4) AS ctrPercent, ROUND(SUM(charge) / NULLIF(SUM(click), 0), 4) AS cpc, ROUND(SUM(gmv_total), 2) AS gmvTotal, ROUND(SUM(gmv_total) / NULLIF(SUM(charge), 0), 2) AS roi, SUM(cart_count) AS cartCount, COUNT(DISTINCT CASE WHEN charge > 0 THEN campaign_id END) AS planCount FROM promo_cost_daily
stat_date BETWEEN #{dateFrom} AND #{dateTo}
AND plan_type = #{planType}
GROUP BY stat_date ORDER BY stat_date

SELECT campaign_id AS campaignId, MAX(campaign_name) AS campaignName, plan_type AS planType, MAX(bid_type) AS bidType, COUNT(DISTINCT stat_date) AS days, ROUND(SUM(charge), 2) AS charge, SUM(ad_pv) AS adPv, SUM(click) AS click, ROUND(SUM(click) / NULLIF(SUM(ad_pv), 0) * 100, 4) AS ctrPercent, ROUND(SUM(charge) / NULLIF(SUM(click), 0), 4) AS cpc, ROUND(SUM(gmv_total), 2) AS gmvTotal, ROUND(SUM(gmv_direct), 2) AS gmvDirect, SUM(order_total) AS orderTotal, ROUND(SUM(gmv_total) / NULLIF(SUM(charge), 0), 2) AS roi, SUM(cart_count) AS cartCount, SUM(collect_total) AS collectTotal, DATE_FORMAT(MAX(update_time), '%Y-%m-%d %H:%i') AS lastCollectedAt FROM promo_cost_daily
stat_date BETWEEN #{dateFrom} AND #{dateTo}
AND plan_type = #{planType}
GROUP BY campaign_id, plan_type
ORDER BY SUM(charge) IS NULL, SUM(charge) DESC
